class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * n
        suffix = [0] * n

        for i in range(1, n):
            prefix[i] = prefix[i - 1] | nums[i - 1]

        for i in range(n - 2, -1, -1):
            suffix[i] = suffix[i + 1] | nums[i + 1]

        max_val = 0
        for i in range(n):
            shifted = nums[i] << k
            result = prefix[i] | shifted | suffix[i]
            if result > max_val:
                max_val = result

        return max_val

