class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        if len(prices) < 2:
            return money

        min1 = min(prices[0], prices[1])
        min2 = max(prices[0], prices[1])

        for i in range(2, len(prices)):
            if prices[i] < min1:
                min2 = min1
                min1 = prices[i]
            elif prices[i] < min2:
                min2 = prices[i]

        if min1 + min2 <= money:
            return money - (min1 + min2)
        else:
            return money

