class Solution:
    def distinctDifferenceArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        prefix = {}
        suffix = {}

        for num in nums:
            suffix[num] = suffix.get(num, 0) + 1

        diff = []
        for i in range(n):
            num = nums[i]
            prefix[num] = prefix.get(num, 0) + 1
            suffix[num] -= 1
            if suffix[num] == 0:
                del suffix[num]

            diff.append(len(prefix) - len(suffix))

        return diff

