class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        if n < 2:
            return n

        left = 0
        max_length = 1
        consecutive_count = 0

        for right in range(1, n):
            if s[right] == s[right - 1]:
                consecutive_count += 1

            while consecutive_count > 1:
                if s[left] == s[left + 1]:
                    consecutive_count -= 1
                left += 1

            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        seen = {0}
        current = 0
        i = 1
        while True:
            current = (current + i * k) % n
            if current in seen:
                break
            seen.add(current)
            i += 1

        return [i + 1 for i in range(n) if i not in seen]

