class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            if not s:
                return target == 0
            for i in range(1, len(s) + 1):
                prefix = int(s[:i])
                if prefix > target:
                    break
                if can_partition(s[i:], target - prefix):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            square = i * i
            if can_partition(str(square), i):
                total += square
        return total

