    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(n):
                if time[j] + 1 <= i:
                    dp[i] = min(dp[i], dp[i - time[j] - 1] + cost[j])
                else:
                    dp[i] = min(dp[i], dp[i - 1])

        return dp[n]

