class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False

        parent = list(range(n))
        size = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                if size[rx] < size[ry]:
                    rx, ry = ry, rx
                parent[ry] = rx
                size[rx] += size[ry]

        prime_to_first_idx = {}
        for i, val in enumerate(nums):
            temp = val
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    while temp % d == 0:
                        temp //= d
                    if d in prime_to_first_idx:
                        union(i, prime_to_first_idx[d])
                    else:
                        prime_to_first_idx[d] = i
                d += 1
            if temp > 1:
                if temp in prime_to_first_idx:
                    union(i, prime_to_first_idx[temp])
                else:
                    prime_to_first_idx[temp] = i

        root = find(0)
        return size[root] == n

class Solution:
