class Solution:
    def maximumSumQueries(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums1)
        pairs = sorted([(nums1[i], nums2[i]) for i in range(n)], reverse=True)
        q_sorted = sorted([(q[0], q[1], i) for i, q in enumerate(queries)], reverse=True)

        ans = [-1] * len(queries)
        stack = deque()
        p_idx = 0

        for x_req, y_req, q_orig in q_sorted:
            while p_idx < n and pairs[p_idx][0] >= x_req:
                x_val, y_val = pairs[p_idx]
                p_idx += 1
                while stack and stack[0][1] <= x_val + y_val:
                    stack.popleft()
                if not stack or stack[0][0] < y_val:
                    stack.appendleft((y_val, x_val + y_val))

            while stack and stack[0][0] < y_req:
                stack.popleft()

            if stack:
                ans[q_orig] = stack[0][1]

        return ans

