class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # dp[mask][i] will store the number of valid permutations of the selected elements (encoded in mask) ending with element i
        dp = [[0] * n for _ in range(1 << n)]

        for i in range(n):
            dp[1 << i][i] = 1

        for mask in range(1 << n):
            for i in range(n):
                if mask & (1 << i):
                    for j in range(n):
                        if mask & (1 << j) and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                            dp[mask][i] = (dp[mask][i] + dp[mask ^ (1 << i)][j]) % MOD

        total = sum(dp[(1 << n) - 1]) % MOD
        return total

