class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            seen = {nums[i]}
            current = 0
            for j in range(i + 1, n):
                if nums[j] not in seen:
                    seen.add(nums[j])
                    has_prev = (nums[j] - 1) in seen
                    has_next = (nums[j] + 1) in seen
                    if not has_prev and not has_next:
                        current += 1
                    elif has_prev and has_next:
                        current -= 1
                total += current
        return total

class Solution:
    def longestString(self, x: int, y: int, z: int) -> int:
        # Use the minimum of x and y to alternate AA and BB
        min_xy = min(x, y)
        # If x != y, we can use one extra string of the type that has more available
        if x != y:
            min_xy += 1
        # Each AA or BB pair contributes 2 to the length, and each AB contributes 2
        return 2 * (min_xy * 2 + z)

