class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        if n == 1:
            return len(words[0])

        # Initialize DP table
        dp = [[[float('inf')] * 26 for _ in range(26)] for _ in range(n)]
        first_char = ord(words[0][0]) - ord('a')
        last_char = ord(words[0][-1]) - ord('a')
        dp[0][first_char][last_char] = len(words[0])

        for i in range(1, n):
            curr_first = ord(words[i][0]) - ord('a')
            curr_last = ord(words[i][-1]) - ord('a')
            prev_first = ord(words[i - 1][0]) - ord('a')
            prev_last = ord(words[i - 1][-1]) - ord('a')

            for f in range(26):
                for l in range(26):
                    if dp[i - 1][f][l] < float('inf'):
                        # Prepend words[i]
                        if l == curr_first:
                            dp[i][curr_last][l] = min(dp[i][curr_last][l], dp[i - 1][f][l] + len(words[i]) - 1)
                        else:
                            dp[i][curr_last][l] = min(dp[i][curr_last][l], dp[i - 1][f][l] + len(words[i]))

                        # Append words[i]
                        if f == curr_last:
                            dp[i][f][curr_first] = min(dp[i][f][curr_first], dp[i - 1][f][l] + len(words[i]) - 1)
                        else:
                            dp[i][f][curr_first] = min(dp[i][f][curr_first], dp[i - 1][f][l] + len(words[i]))

        min_length = float('inf')
        for f in range(26):
            for l in range(26):
                min_length = min(min_length, dp[n - 1][f][l])

        return min_length

